// Exact card glyphs exported straight from the "Places" Figma (SVG paths
// copied verbatim) so the discover cards match the design 1:1 rather than
// approximating with MUI icons.
//
// `size` sets the glyph HEIGHT and accepts either a number (px) or any CSS
// length string (the cards pass `cqw` values so icons scale with card width).
// Width resolves from the SVG viewBox's intrinsic aspect ratio.

interface IconProps {
  size?: number | string
  color?: string
}

function glyphStyle(size: number | string): React.CSSProperties {
  return { display: 'block', height: typeof size === 'number' ? `${size}px` : size, width: 'auto' }
}

