// X close glyph (from the modal's CTAX, 40×40 — the button provides the dark
// rounded background; this is just the stroke).
function CloseGlyph({ size = 40 }: IconProps) {
  return (
    <svg viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" style={glyphStyle(size)}>
      <path d="M25.8828 14.1174L14.1184 25.8818" stroke="#FCFCFC" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M25.8828 25.8826L14.1184 14.1182" stroke="#FCFCFC" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

